package com.agacostays.payment.controller;
import com.agacostays.payment.dto.request.*; import com.agacostays.payment.dto.response.*; import com.agacostays.payment.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/restaurant/payments") public class RestaurantPaymentController { private final PaymentService service; public RestaurantPaymentController(PaymentService s){service=s;} @PostMapping("/create") public ResponseEntity<ApiResponse<PaymentResponse>> create(@Valid @RequestBody RestaurantPaymentRequest r,@RequestHeader(value="Idempotency-Key",required=false)String k){return ResponseEntity.ok(ApiResponse.ok("Restaurant payment order created",service.createRestaurantPayment(r,k)));} @PostMapping("/verify") public ResponseEntity<ApiResponse<VerifyPaymentResponse>> verify(@Valid @RequestBody VerifyPaymentRequest r){return ResponseEntity.ok(ApiResponse.ok("Restaurant payment verified",service.verifyRestaurantPayment(r)));} @GetMapping("/order/{orderId}") public ResponseEntity<ApiResponse<PageResponse<PaymentResponse>>> byOrder(@PathVariable String orderId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(ApiResponse.ok("Restaurant payments fetched",service.restaurantOrderPayments(orderId,org.springframework.data.domain.PageRequest.of(page,size))));} }
